GetActivity:
query GetActivity($feedType: ActivityFeed, $first: Int, $after: String) {
  activity(feedType: $feedType, first: $first, after: $after) {
    nodes {
      id
      eventCategory
      createdAt
      user {
        id
        username
        slug
        avatarUrl(size: SMALL)
      }
      eventable {
        ... on GamePurchase {
          game {
            id
            name
            coverUrl(size: SMALL)
          }
          completionStatus
          rating
        }
        ... on FavoriteGame {
          game {
            id
            name
            coverUrl(size: SMALL)
          }
        }
        ... on Relationship {
          followed {
            id
            username
            slug
            avatarUrl(size: SMALL)
          }
        }
        ... on User {
          id
          username
          slug
          avatarUrl(size: SMALL)
        }
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

